import (
	"net/http"
	"testing"
)

// The read-only views of the caller's data must require a token, like the
// other /v1/me routes. Without one there is no user, and the handler used to
// dereference a nil user and panic.
func TestExportAndStatsRequireToken(t *testing.T) {
	c := newClient(t)
	c.create("tok-ana", `{"text":"mine","in":"1h"}`)
	for _, path := range []string{"/v1/me/export", "/v1/me/stats"} {
		if code := c.do("", http.MethodGet, path, "", nil); code != http.StatusUnauthorized {
			t.Errorf("GET %s without token: status %d, want 401", path, code)
		}
	}
	if code := c.do("tok-ana", http.MethodGet, "/v1/me/export", "", nil); code != http.StatusOK {
		t.Errorf("GET /v1/me/export with token: status %d, want 200", code)
	}
}
"}

